/**
 * Public MCP tool manifest — 71 canonical tools across 4 tiers.
 *
 * Canonical manifest of tools exposed across Core, Plus, Pro, and Realm tiers.
 * Full schemas + handlers live on the hosted server; this manifest is here for
 * directory listings, discovery cards, and client-side validation.
 */
import { z } from "zod";
export const PUBLIC_TOOLS = [
    { name: "create_source", category: "capture", tier: "core", summary: "[Vault] Save a conversation, document, or transcript to the vault. Sources always live in the vault — they are never owned by containers. Automatically extracts decisions, frameworks, key passages, and more with full provenance. Use when the user says 'save this conversation,' 'send this to my vault,' 'remember this,' or 'import this document.'" },
    { name: "update_source", category: "capture", tier: "core", summary: "[Vault] Update a saved conversation with new content. Supports two modes: 'append' (default, safer — adds new content to the end) and 'replace' (full replacement with a more complete version). Extracts only the NEW meaning since last save. Use when the user says 'update my vault with this,' 'save the latest,' or for periodic session saving." },
    { name: "delete_source", category: "capture", tier: "core", summary: "[Vault] Soft-delete a source. Seeds extracted from this source are NOT deleted — they retain provenance." },
    { name: "trigger_extraction", category: "extraction", tier: "core", summary: "[Vault] Run Neuron extraction on a source. Uses default 8-category extraction, or a specific skill for targeted extraction. When skillId is provided, the skill's instructions and schema govern what gets extracted." },
    { name: "get_source", category: "discovery", tier: "core", summary: "Open one known source by id or title and read everything in it — abstract, all seeds grouped by their 8 canonical categories and any skill-defined categories, and assets. Use this when you already have a specific source in mind. Not for searching — use search_vault to find seeds across the vault, or search_sources to locate which source you want first. By default the response includes raw content; for sources larger than ~100k characters the content is auto-omitted with omittedReason set, in which case re-request with explicit include: ['content'] if you really need it." },
    { name: "search_vault", category: "discovery", tier: "core", summary: "Find seeds across your entire vault by semantic query. Use this when you want extracted meaning — decisions, frameworks, golden passages, or skill-defined categories like \"Product Moves\" — regardless of which source they came from. The category filter accepts the 8 canonical categories AND any skill-defined category name; it matches both the stored form (product_moves) and the human-readable form (Product Moves). Not for finding whole sources — use 'search_sources' for that, or 'get_source' to open one you already know." },
    { name: "search_sources", category: "discovery", tier: "core", summary: "Find sources (whole conversations/documents) by title, date, type, or keyword — the card catalog of your vault. Use this when you want to locate documents, not the meaning inside them. Not for retrieving extracted seeds — use \search_vault\ to query seeds across sources, or \get_source\ once you know which source you want." },
    { name: "get_vault_summary", category: "discovery", tier: "core", summary: "Returns a high-level snapshot of the entire vault: source count, seed count, category distribution, recent sources, and topic clusters. Use at session start or when you need to understand the full knowledge landscape." },
    { name: "get_vault_gaps", category: "discovery", tier: "core", summary: "Analyze the vault's coverage — categories with low density, topics mentioned but unexplored, unextracted sources. Use this to decide what to explore next." },
    { name: "get_capabilities", category: "discovery", tier: "core", summary: "Introspect the current MCP session and orient yourself to the vault surface. Returns: which canonical tools you can actually call right now (grouped by category), the canonical primitives and how they relate, and the typical-flow navigation spine. Call at session start to preflight what's permitted AND to load the right mental model. Pair with get_vault_summary for a snapshot of what's *in* the vault." },
    { name: "list_local_models", category: "local_silicon", tier: "core", summary: "List all local models installed in the Ollama instance running on the host machine (e.g. Llama 3.2, custom Modelfiles) along with parameter sizes and memory footprint at $0.00 compute cost." },
    { name: "query_local_model", category: "local_silicon", tier: "core", summary: "Execute local inference or reasoning directly on the host machine's Apple Silicon chip or local GPU via Ollama. 100% private, zero-custody, $0.00 compute cost." },
    { name: "compose_workspace", category: "workspace", tier: "plus", summary: "[Workspace] Create a fully configured workspace with Container, Studios, Lanes, and governance seeds. This is the 'talk it into being' operation — describe what you need, and the workspace appears. Touches workspace primitives only; the vault is unaffected. Use when the user wants to create a project board, organize a goal, structure a client/project/life domain, turn a messy plan into lanes/cards, or talk a workspace into existence. Returns containerUrl + per-studio studioUrl for direct deeplinks." },
    { name: "resolve_workspace", category: "workspace", tier: "plus", summary: "[DEPRECATED: Prefer list_containers, list_studios, or passing human-readable names directly into entity tools] Translate human-readable workspace names to system IDs." },
    { name: "list_containers", category: "workspace", tier: "plus", summary: "[Workspace] List top-level containers (Mission Horizons). Scoped by default to the active Realm to prevent cross-domain leakage. Pass optional realmId to inspect a specific realm, or set allRealms: true for an account-wide overview. ${ENTITY_REF_CONVENTION_NOTE}" },
    { name: "create_container", category: "workspace", tier: "plus", summary: "[Workspace] Create a new top-level container (Mission Horizon). Containers organize studios into broad operational domains. Use when the user wants a new project domain at the top level; for a fully configured workspace with studios + lanes in one call, prefer compose_workspace." },
    { name: "update_container", category: "workspace", tier: "plus", summary: "Update a container's name, description, or type. containerType changes are blocked once any agent is assigned (prevents orphaning agent configs); free to change while no agent is assigned." },
    { name: "delete_container", category: "workspace", tier: "plus", summary: "Delete a container. Studios and lanes are deleted, but seeds are orphaned (kept in vault). Requires confirm=true." },
    { name: "get_container", category: "workspace", tier: "plus", summary: "Get a container's full structure — studios with their lanes, framework seeds, routing rules, and optionally recent seeds. This is how the morning brief reads each desk's state." },
    { name: "get_container_structure", category: "workspace", tier: "plus", summary: "[Workspace] Read a container's full organizational structure — all studios, lanes, card counts. Pass either containerId or containerName. Note: This is a deep structural tree inspector. To list top-level domains, prefer list_containers." },
    { name: "get_container_stats", category: "workspace", tier: "plus", summary: "Quick stats for a container — studio count, seed count per studio, lane counts, category breakdown. Designed for morning brief at-a-glance summaries." },
    { name: "list_studios", category: "studios", tier: "plus", summary: "[Workspace] List Studios within a container or across the active Realm. Pass containerId or containerName to filter to a specific container." },
    { name: "create_studio", category: "studios", tier: "plus", summary: "[Workspace] Create a studio workspace within a container. Studios are configurable surfaces with an ordered set of modules (source, writer, deck, brief, production, etc.), pinned sources, and lanes for organizing cards. Pass either containerId or containerName. Defaults to [source, writer, deck] when modules omitted. Use when the user wants to add a new working surface inside an existing container (e.g., 'add a research studio to my Finance container'); for a brand-new container with studios from scratch, prefer compose_workspace." },
    { name: "update_studio", category: "studios", tier: "plus", summary: "Update a studio's name, description, or module configuration." },
    { name: "delete_studio", category: "studios", tier: "plus", summary: "Delete a studio and its lanes. Seeds are orphaned. Requires confirm=true." },
    { name: "get_deck_state", category: "studios", tier: "plus", summary: "Read the full deck state for a studio — all lanes with their cards. Use when you need to know what work is active. Pass either studioId or studioName." },
    { name: "pin_source", category: "studios", tier: "plus", summary: "[Workspace] Pin a source to a studio so its seeds load into foreground context. Creates a workspace-side join row; the source itself is unmutated. Pins are an uncapped, ephemeral working set. Use when the user wants to bring a vault source into a studio's working set (e.g., 'pin the strategy doc to Sprint Planning'); the source is not moved — only referenced." },
    { name: "unpin_source", category: "studios", tier: "plus", summary: "[Workspace] Remove a source from a studio's pinned sources. Removes the workspace-side join row only; the source itself is unaffected. Use when the user is done referencing a source in a particular studio (e.g., 'unpin the old draft from Active Sprints'); does not delete the source." },
    { name: "list_pins", category: "studios", tier: "plus", summary: "List sources currently pinned to a studio with seed counts. Returns metadata + abstract by default — call get_source on a specific pin when you need full content." },
    { name: "list_lanes", category: "cards", tier: "plus", summary: "List all lanes in a studio with card counts and optional preview (first 3 card titles). Pass either studioId or studioName." },
    { name: "create_lane", category: "cards", tier: "plus", summary: "[Workspace] Add a lane to a studio's deck. Lanes are columns that hold cards. Pass either studioId or studioName. Use when the user wants a new column/swimlane inside an existing studio (e.g., 'add a Blocked lane', 'add a Calendar lane'). For a fresh studio with all lanes specified, set them via compose_workspace or create_studio instead." },
    { name: "update_lane", category: "cards", tier: "plus", summary: "Rename a lane, update its position, or modify metadata." },
    { name: "delete_lane", category: "cards", tier: "plus", summary: "Delete a lane. Seeds in the lane are moved to the studio's first remaining lane before deletion." },
    { name: "get_lane_contents", category: "cards", tier: "plus", summary: "Get all seeds in a specific lane. Faster than filtered search for reading a single lane's contents — e.g., 'show me everything in the Qualified lane'." },
    { name: "list_cards", category: "cards", tier: "plus", summary: "[Workspace] List cards within a studio or specific lane. Pass studioId/studioName or laneId/laneName. Supports optional status filter and limit." },
    { name: "get_card", category: "cards", tier: "plus", summary: "Read a single card's full content, metadata, and location (lane, studio, container). Use when GPT or the user needs the full body of a specific card by ID." },
    { name: "create_card", category: "cards", tier: "plus", summary: "[Workspace] Drop a card into a lane. Cards are the workspace coordination surface (tasks, notes, references, handoff packets). Two types: 'note' for workspace-native content, 'reference' for pointers at a vault source or seed. Pass laneId, or resolve by name: laneName + (studioId or studioName). Use when the user wants to capture a task, note, idea, or pointer-to-source in a specific lane; this is the most common writing operation in workspace mode. Returns laneName, studioName, containerName, and a studio deeplink (cardUrl) so the user can open it." },
    { name: "update_card", category: "cards", tier: "plus", summary: "Update a card's title, content, status, or semantic shape (cardType, emergenceType, draftStatus). Use move_card to change which lane a card lives in. Use this for natural commands like 'rename to ...', 'mark it ready', 'tag as emergence vector'." },
    { name: "move_card", category: "cards", tier: "plus", summary: "Move a card to a different lane. Lane can be specified by ID or by name within the card's current studio. Use this for natural commands like 'move this card to Shipped'." },
    { name: "delete_card", category: "cards", tier: "plus", summary: "Delete a card from its lane. Soft-delete by default (recoverable); pass hard=true for a true DB delete. The vault is unaffected — even reference cards just remove the pointer." },
    { name: "graduate_card", category: "cards", tier: "plus", summary: "[Workspace → Vault] Graduate a workspace card into a canonical vault Source. This is the bridge across primitives: cards are ephemeral workspace coordination objects; sources are durable vault ground truth. Graduation creates a Source from the card's content (derivationType='conversation_graduated', parent linkage preserved) and optionally triggers extraction. Use when a card has earned permanence — its content would create friction in a future session if it stayed inside the workspace and got deleted with the lane." },
    { name: "request_brief", category: "research", tier: "plus", summary: "Synthesize a research brief across vault sources on a topic. Two modes: mode: 'full' (default) runs async — Multiplist synthesizes a research document and saves it as a vault source; returns immediately with a sourceId, poll via get_brief_status until complete, then read via get_source. mode: 'retrieval_only' returns synchronously with ranked seeds + constellation links — no LLM call on Multiplist's backend, no vault write. Use retrieval_only when you want Archivist-quality retrieval to synthesize yourself. After synthesizing from retrieval_only results, offer the user: 'Want me to save this research to your vault?' If yes, call create_source with your synthesized response (sourceType='archivist_brief', tags=['archivist-synthesis', 'retrieval-capture'])." },
    { name: "get_brief_status", category: "research", tier: "plus", summary: "Poll a research brief's status. Accepts sourceId (preferred — what request_brief returns) or briefId (legacy — for briefs that pre-date the brief-as-source collapse). Status values: 'synthesizing' (brief being assembled, no content yet), 'extracting' (legacy in-flight status), 'complete' (brief ready — retrieve via get_source), 'error' (synthesis failed; details in metadata.error)." },
    { name: "create_vault_folder", category: "collections", tier: "plus", summary: "Create a new manual collection folder or dynamic smart search folder in the user's Vault." },
    { name: "delete_vault_folder", category: "collections", tier: "plus", summary: "Delete a Vault folder or smart collection. Underlying sources remain safe in your vault." },
    { name: "rename_vault_folder", category: "collections", tier: "plus", summary: "Rename an existing Vault folder or smart collection." },
    { name: "add_sources_to_folder", category: "collections", tier: "plus", summary: "Add one or more sources into a manual Vault folder." },
    { name: "remove_source_from_folder", category: "collections", tier: "plus", summary: "Remove a source from a manual Vault folder. (The underlying source remains intact in the Vault)." },
    { name: "batch_extract", category: "extraction", tier: "plus", summary: "[Vault] Start a batch extraction across multiple sources. Processes them sequentially using efficient unified mode. Returns a job ID for progress tracking." },
    { name: "batch_status", category: "extraction", tier: "plus", summary: "Check the progress of a batch extraction job." },
    { name: "create_skill", category: "skills", tier: "plus", summary: "Create a new skill. Skills define WHAT to extract from specific content types — custom fields, scoring criteria, domain-specific analysis. Aero writes these conversationally. Default skillType is 'extraction' (domain packs that shape how sources become seeds); pick 'evaluation' for Archivist brief evaluators, or 'production' for Assemblist content pipelines." },
    { name: "list_skills", category: "skills", tier: "plus", summary: "Browse available extraction skills — domain-specific recipes that define what to extract beyond the canonical 8 categories. Returns skill name, description, domain, type, and field count. To see a skill's actual extraction fields (which are the category names usable in search_vault's category filter), follow up with get_skill." },
    { name: "get_skill", category: "skills", tier: "plus", summary: "Read one skill's full extraction recipe — instructions, schema with field names, and trigger conditions. The schema[].field values are the category names you can pass to search_vault's category filter to find seeds extracted by this skill." },
    { name: "match_skills", category: "skills", tier: "plus", summary: "Find which extraction skills apply to a given source based on content and trigger conditions. Use when you've imported a source and want to know which skills would produce the most relevant custom extraction alongside the canonical 8 categories. Only returns extraction-type skills — evaluation and production skills are routed through Archivist and Assemblist respectively." },
    { name: "update_skill", category: "skills", tier: "plus", summary: "Update a custom skill's name, description, domain, instructions, or skillType." },
    { name: "delete_skill", category: "skills", tier: "plus", summary: "Delete a custom extraction skill. Seeds already extracted with this skill are not deleted." },
    { name: "add_annotation", category: "annotate", tier: "plus", summary: "[Vault] Write an annotation to a source — a real-time extraction-style note by the source's own author while they are working on it. Annotations are the author's own voice, distinct from seeds (Neuron extraction) and marginalia (later-mind marks). Use when the source's author wants to mark their own decisions, insights, or notes during authoring." },
    { name: "add_marginalia", category: "annotate", tier: "plus", summary: "[Vault] Write marginalia to an existing source — a correction, tension flag, evolution narrative, or commentary by a later mind. Marginalia is distinct from seeds (Neuron extraction) and annotations (author's own marks). Every marginalia records its scribe identity and markType for cross-AI provenance. Use when correcting prior content, flagging contradictions, narrating concept evolution, or adding enriching commentary." },
    { name: "list_source_assets", category: "assets", tier: "plus", summary: "List detected assets (work products, drafts, code blocks, tables) found in a source prebiotically. Returns detection suggestions with exact character ranges, lines, types, confidence, and formatted snippets. SURFACE BEFORE COMPUTE: external models (Claude/ChatGPT) must inspect these assets before re-generating code and quote them verbatim with exact provenance offsets without summarizing or hallucinating alterations. Use rescue_excerpt to promote confirmed assets into sovereign sub-sources." },
    { name: "rescue_excerpt", category: "assets", tier: "plus", summary: "Lift a detected draft, code block, or substantial content chunk from a source into its own sub-source. The excerpt becomes a sovereign vault primitive with verbatim content and provenance linking back to its parent source. Use when a source contains work products worth rescuing — guidebook entries, spec sections, email drafts, code modules." },
    { name: "scaffold_agent_runway", category: "agent", tier: "pro", summary: "[Workspace] Scaffold the canonical 5-Lane Agent Runway ('📥 Intake', '⚡ Doing', '⏸️ Needs Context', '👁️ Review', '🚢 Shipped & Vaulted') for a studio. Idempotent — will not duplicate existing lanes." },
    { name: "get_desk_state", category: "agent", tier: "pro", summary: "Read the full workstation desk orientation for a studio: assigned resident agent, equipped 2-4 tool bouquet, 5-lane agent runway deck status, and active studio context brief. Pass either studioId or studioName." },
    { name: "query_agent_log", category: "agent", tier: "pro", summary: "Read external-agent telemetry — what agents (Greenroom, BD, Funding Scout, etc.) have been doing in your vault. Filter by agentIdentifier, container, workflow, outcome, or date range. Each entry records the agent's plan, actions, outcome, and cost; rows flagged with promotion signals (shouldPromoteToMemory, shouldNotifyHuman) are review-worthy. Distinct from audit_log (low-level MCP audit) — this is operational visibility for agent oversight." },
    { name: "list_production_skills", category: "production", tier: "pro", summary: "List available Production Skills (Assemblist work orders) grouped by domain. Production Skills produce deliverables from vault knowledge — articles, briefs, proposals, voice captures, and more. Use to discover what can be produced, then invoke with produce_deliverable." },
    { name: "produce_deliverable", category: "production", tier: "pro", summary: "Invoke a Production Skill to generate a deliverable from vault knowledge. This is the Assemblist engine — it takes a skill (work order), vault sources for context, and optionally a voice pack, then produces structured output (articles, briefs, proposals, etc.). The output is auto-saved to the Outbox. Use after list_production_skills to discover available skills." },
    { name: "get_context", category: "research", tier: "pro", summary: "Get a scoped context snapshot from the vault — recent seeds, top tags, and category stats. Use this to understand what the user is working on." },
    { name: "list_realms", category: "realm", tier: "realm", summary: "[Realm] List all Realms available to your account (e.g. Multiplist, Gaia Futures, Client Workspaces). Returns realm id, name, description, and default status." },
    { name: "get_current_realm", category: "realm", tier: "realm", summary: "[Realm] Get the currently active Realm context for this AI session. Operations against the vault (sources, seeds, extractions) are partitioned to this realm." },
    { name: "switch_realm", category: "realm", tier: "realm", summary: "[Realm] Switch your active Realm operating context. Future vault reads and writes will operate in the target realm." },
    { name: "share_source_to_realm", category: "realm", tier: "realm", summary: "[Realm] Share an existing extracted source to another Realm ($0 re-extraction cost). Adds a realm pointer so all extracted seeds and provenance instantly appear in the target realm." },
    { name: "move_source_to_realm", category: "realm", tier: "realm", summary: "[Realm] Transfer a source exclusively to a different Realm. Unclaims from source realm and claims into target realm." },
];
export const PUBLIC_TOOL_NAMES = PUBLIC_TOOLS.map((t) => t.name);
export const PUBLIC_TOOL_COUNT = PUBLIC_TOOLS.length;
// Zod-checked sanity guard — exactly 71 canonical public tools.
export const publicToolsSchema = z
    .array(z.object({ name: z.string(), category: z.string(), tier: z.string(), summary: z.string() }))
    .length(71);
publicToolsSchema.parse(PUBLIC_TOOLS);
